import 'dart:convert';

import 'package:flutter/material.dart';
import 'package:open//////////////////////////////////////////////////////////////////////////api/openai_api.dart';

class EventIntentGuessing extends StatefulWidget {
  const EventIntentGuessing({Key? key}) : super(key: key);

  @override
  _EventIntentGuessingState createState() => _EventIntentGuessingState();
}

class _EventIntentGuessingState extends State<EventIntentGuessing> {
  final String openAIKey = 'YOUR_OPENAI_API_KEY';
  final OpenAIApi openAIApi = OpenAIApi(openAIKey);
  String event = '';
  String intention = '';
  String guess = '';

  void fetchIntent(String event) async {
    Map<String, dynamic> response = await openAIApi.complete(
      model: 'text-davinci-003',
      prompt: 'Given the event: "$event", what is the most likely intention of PersonX? ',
    );
    setState(() {
      intention = json.decode(response['choices'][0]['message'])['intention'];
      guess = json.decode(response['choices'][0]['message'])['response'];
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text('Event Intent Guessing'),
      ),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              'Event:',
              style: TextStyle(fontWeight: FontWeight.bold),
            ),
            SizedBox(height: 8),
            SizedBox(
              width: double.infinity,
              child: TextField(
                onChanged: (value) {
                  setState(() {
                    event = value;
                  });
                },
              ),
            ),
            SizedBox(height: 16),
            Text(
              'Intention of PersonX:',
              style: TextStyle(fontWeight: FontWeight.bold),
            ),
            Text(intention),
            SizedBox(height: 16),
            Text(
              'Recommended response (guessed):',
              style: TextStyle(fontWeight: FontWeight.bold),
            ),
            Text(guess),
            SizedBox(height: 16),
            ElevatedButton(
              onPressed: () {
                setState(() {
                  intention = '';
                  guess = '';
                  fetchIntent(event);
                });
              },
              child: Text('Guess'),
            ),
          ],
        ),
      ),
    );
  }
} 

