        jdbcTemplate.execute("CREATE TABLE invoice (invoice_number VARCHAR2(20), customer_id VARCHAR2(20), invoice_date DATE, total_amount NUMBER)");
    }

    @Test
    public void someTest() {
        // implement your test logic
    }
