Получив имена анимаций, вы можете управлять ими с помощью JavaScript и WebXR API. 

Например, для воспроизведения определенной анимации:

```javascript
const animationToPlay = 'animation1';

session.addEventListener('end', () => {
  session.end();
});

session.addEventListener('frame-end', async (event) => {
  try {
    const presentation = event.target;

    if (presentation.renderState.hasStateChanged) {
      presentation.renderState.hasStateChanged = false;

      const xrRefSpace = await session.requestReferenceSpace(XRReferenceSpaceType.local);
      const presentRefSpace = await session.requestReferenceSpace(XRReferenceSpaceType.local);

      const clippingSpace = await presentRefSpace.getWorldRay({
        x: event.input.source.x * 2 - 1,
        y: -(event.input.source.y * 2 - 1),
      });

      const model = await presentation.getEmbeddedResource('assets/models/3d_object.glb');

      const animation = model('_animation').find(animation => animation.name === animationToPlay);

      // Установить анимацию на объект
      model.setAnimation(animation);

      // Анимировать объект в реальном времени
      presentation.renderState_changed += async () => {
        await presentation.updateRenderState();
