public class FlowerCategorizer {

    private static final Map<String, String> categoryNames = new HashMap<String, String>() {{
        put("Li", "Lilac");
        put("Da", "Daisy");
        put("Ma", "Marigold");
        put("Ch", "Chrysanthemum");
    }};

    private Map<String, List<String>> flowerMap = new HashMap<>();

