                list.add(flower);
                flowerMap.put(category, list);
            }
        }
    }

    public Map<String, List<String>> getFlowerCategories() {
        return flowerMap;
    }

    private String getCategoryName(String flowerName) {
        Pattern pattern = Pattern.compile("^(?:" + String.join("|", categoryNames.keySet()) + ").*");
        Matcher matcher = pattern.matcher(flowerName);
        if (matcher.find()) {
            String prefix = matcher.group(1);
            return categoryNames.get(prefix);
